select count(1)
from social_match_record
where user_a = #{userA}
  and user_b = #{userB}
  and match_status = 'ACTIVE'

select conversation_id, user_a, user_b, last_sender_id, last_message, last_message_time,
       user_a_unread, user_b_unread, created_at, updated_at
from social_chat_conversation
where user_a = #{userA}
  and user_b = #{userB}
limit 1

